// Golden Crust Bakery — shared opening-hours, menu, and pricing logic.

type Weekday = 'monday' | 'tuesday' | 'wednesday' | 'thursday' | 'friday' | 'saturday' | 'sunday';

type Category = 'Breads' | 'Pastries' | 'Cakes' | 'Drinks';

type DietaryTag = 'gluten' | 'dairy' | 'nuts' | 'egg' | 'vegan';

interface OpeningSpan {
  opens: string;
  closes: string;
}

interface DayHours {
  day: Weekday;
  spans: OpeningSpan[];
}

type OpeningHoursTable = DayHours[];

interface HolidayClosure {
  date: string;
  name: string;
}

interface OpeningStatus {
  open: boolean;
  label: string;
  day: Weekday;
  spans: OpeningSpan[];
}

interface WeeklyHoursRow {
  day: Weekday;
  label: string;
  spans: OpeningSpan[];
  closed: boolean;
}

interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: Category;
  tags: DietaryTag[];
  freshBake: boolean;
}

interface MenuFilters {
  category?: Category;
  tag?: DietaryTag;
  query?: string;
}

const WEEKDAYS: Weekday[] = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

const DAY_LABELS: Record<Weekday, string> = {
  monday: 'Monday',
  tuesday: 'Tuesday',
  wednesday: 'Wednesday',
  thursday: 'Thursday',
  friday: 'Friday',
  saturday: 'Saturday',
  sunday: 'Sunday'
};

const CATEGORY_ORDER: Category[] = ['Breads', 'Pastries', 'Cakes', 'Drinks'];

/**
 * Convert an "HH:MM" 24-hour clock string into minutes past midnight.
 *
 * @param value - a clock string in "HH:MM" form
 * @returns minutes past midnight, or -1 when the input is malformed
 */
function clockToMinutes(value: string): number {
  if (typeof value !== 'string') {
    return -1;
  }
  const match = /^([0-9]{1,2}):([0-9]{2})$/.exec(value.trim());
  if (match === null) {
    return -1;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return -1;
  }
  return hours * 60 + minutes;
}

/**
 * Map a JavaScript day index (0 = Sunday) onto the canonical weekday key.
 *
 * @param dayIndex - value from Date.prototype.getDay()
 * @returns the matching weekday key
 */
function weekdayFromIndex(dayIndex: number): Weekday {
  const mapping: Weekday[] = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const index = ((dayIndex % 7) + 7) % 7;
  return mapping[index];
}

/**
 * Format a Date as an ISO "YYYY-MM-DD" calendar date using local time.
 *
 * @param value - the date to format
 * @returns the ISO calendar date string
 */
function formatIsoDate(value: Date): string {
  const year = value.getFullYear();
  const month = value.getMonth() + 1;
  const day = value.getDate();
  const paddedMonth = month < 10 ? '0' + String(month) : String(month);
  const paddedDay = day < 10 ? '0' + String(day) : String(day);
  return String(year) + '-' + paddedMonth + '-' + paddedDay;
}

/**
 * Determine whether a given ISO date string appears in the closure list.
 *
 * @param holidays - the holiday-closure entries to inspect
 * @param isoDate - the ISO "YYYY-MM-DD" date to look for
 * @returns true when the date is a holiday closure
 */
function isHolidayClosure(holidays: HolidayClosure[], isoDate: string): boolean {
  if (!Array.isArray(holidays)) {
    return false;
  }
  for (let i = 0; i < holidays.length; i += 1) {
    const entry = holidays[i];
    if (entry !== null && entry !== undefined && entry.date === isoDate) {
      return true;
    }
  }
  return false;
}

/**
 * Find the hours entry for a specific weekday in the shared hours table.
 *
 * @param hours - the shared opening-hours table
 * @param day - the weekday key to look up
 * @returns the matching day entry, or null when the day is absent
 */
function findDay(hours: OpeningHoursTable, day: Weekday): DayHours | null {
  if (!Array.isArray(hours)) {
    return null;
  }
  for (let i = 0; i < hours.length; i += 1) {
    const entry = hours[i];
    if (entry !== null && entry !== undefined && entry.day === day) {
      return entry;
    }
  }
  return null;
}

/**
 * Test whether a minute-of-day value sits inside any opening span.
 * Span start is inclusive; span end is exclusive. Spans that close after
 * midnight (closes <= opens) wrap into the following day.
 *
 * @param spans - the day's opening spans
 * @param minuteOfDay - minutes past midnight of the instant being tested
 * @param rolloverMinutes - minutes past midnight carried from the previous day
 * @returns true when the instant falls inside an opening span
 */
function spansAreOpen(spans: OpeningSpan[], minuteOfDay: number, rolloverMinutes: number): boolean {
  if (!Array.isArray(spans)) {
    return false;
  }
  for (let i = 0; i < spans.length; i += 1) {
    const span = spans[i];
    if (span === null || span === undefined) {
      continue;
    }
    const openMinutes = clockToMinutes(span.opens);
    const closeMinutes = clockToMinutes(span.closes);
    if (openMinutes < 0 || closeMinutes < 0) {
      continue;
    }
    if (closeMinutes > openMinutes) {
      if (minuteOfDay >= openMinutes && minuteOfDay < closeMinutes) {
        return true;
      }
    } else if (closeMinutes < openMinutes) {
      if (minuteOfDay >= openMinutes) {
        return true;
      }
      if (rolloverMinutes >= 0 && rolloverMinutes < closeMinutes) {
        return true;
      }
    } else {
      if (minuteOfDay >= openMinutes) {
        return true;
      }
      if (rolloverMinutes >= 0) {
        return true;
      }
    }
  }
  return false;
}

/**
 * Compute the previous weekday key for a given weekday.
 *
 * @param day - the weekday whose predecessor is needed
 * @returns the preceding weekday key
 */
function previousWeekday(day: Weekday): Weekday {
  const index = WEEKDAYS.indexOf(day);
  if (index <= 0) {
    return 'sunday';
  }
  return WEEKDAYS[index - 1];
}

