  const result: ValidationResult = validateOrderForm(order, now);
  if (!result.valid) {
    return {
      reference: '',
      values: result.values,
      lineTotal: '',
      message: 'There is a problem with your enquiry: ' + result.liveRegionMessage + ' Your entered details have been kept.'
    };
  }

  const reference: string = generateOrderReference(now, 1);
  const quantity: number = parseQuantity(result.values.quantity) ?? 1;
  const pricePence: number = 200;
  const lineTotal: string = formatGBP(pricePence * quantity);

  return {
    reference: reference,
    values: result.values,
    lineTotal: lineTotal,
    message: 'Thank you, ' + result.values.name.trim() + '. Your order ' + reference + ' is confirmed.'
  };
}

